INSERT INTO cms_revision(content_key,locale,revision,body) VALUES('privacy','pt',1,'{"metaTitle": "Plataforma tecnológica para organizações esportivas · DEPORTECUADOR", "metaDescription": "Conectamos gestão, talento e tecnologia para que sua organização avance.", "t35": "Política de privacidade", "t45": "Minuta para revisão. Não constitui uma política jurídica aprovada.", "t46": "Responsável: DeportEcuador, Quito, Equador. Contato: info@deportecuador.com.ec.", "t47": "Utilizamos os dados da organização e de contato para responder a pedidos de demonstração ou assessoria e acompanhá-los. Não solicitamos dados sensíveis nestes formulários.", "t48": "As informações poderão ser tratadas por provedores de hospedagem e e-mail, com acordos e controles a documentar antes da produção. Transferências internacionais, bases jurídicas e prazos de retenção estão sujeitos à validação.", "t49": "Você pode solicitar informações, acesso, retificação, eliminação ou outros direitos aplicáveis pelo e-mail info@deportecuador.com.ec. A identidade legal do responsável, prazos, destinatários e mecanismos de reclamação devem ser completados e revisados antes do lançamento público.", "t50": "Esta versão não inclui publicidade nem análises de terceiros. A preferência de idioma é salva localmente no navegador."}');
