CREATE TABLE cms_document (
 content_key VARCHAR(80) NOT NULL, locale VARCHAR(2) NOT NULL,
 label VARCHAR(180) NOT NULL, route VARCHAR(160) NOT NULL, schema_json TEXT NOT NULL,
 state VARCHAR(12) NOT NULL DEFAULT 'PUBLISHED' CHECK (state IN ('DRAFT','PUBLISHED','ARCHIVED')),
 visible BOOLEAN NOT NULL DEFAULT TRUE, version BIGINT NOT NULL DEFAULT 1,
 working_revision INTEGER NOT NULL DEFAULT 1, published_revision INTEGER,
 updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
 PRIMARY KEY(content_key,locale)
);
CREATE TABLE cms_revision (
 content_key VARCHAR(80) NOT NULL, locale VARCHAR(2) NOT NULL, revision INTEGER NOT NULL,
 body TEXT NOT NULL, actor_id UUID REFERENCES admin_user(id),
 created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
 PRIMARY KEY(content_key,locale,revision), FOREIGN KEY(content_key,locale) REFERENCES cms_document(content_key,locale)
);
CREATE TABLE cms_event (
 id UUID PRIMARY KEY, content_key VARCHAR(80) NOT NULL, locale VARCHAR(2) NOT NULL,
 actor_id UUID REFERENCES admin_user(id), action VARCHAR(30) NOT NULL, revision INTEGER NOT NULL,
 created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY(content_key,locale) REFERENCES cms_document(content_key,locale)
);
CREATE INDEX cms_event_document ON cms_event(content_key,locale,created_at);
